def authority(url:str)->str:
    if 'dailymed.nlm.nih.gov' in url: return 'PRIMARY_FDA_DAILYMED_LABEL'
    if 'osha.gov' in url: return 'PRIMARY_FEDERAL_REGULATION_OSHA'
    if 'cdc.gov' in url: return 'PRIMARY_FEDERAL_CDC_NIOSH'
    if 'samhsa.gov' in url: return 'PRIMARY_FEDERAL_SAMHSA'
    if 'ncsbn.org' in url or 'nclex.com' in url: return 'PRIMARY_NCSBN'
    if 'va.gov' in url or 'ethics.va.gov' in url: return 'PRIMARY_FEDERAL_VA'
    if 'hhs.gov' in url: return 'PRIMARY_FEDERAL_HHS'
    if 'niddk.nih.gov' in url or 'ninds.nih.gov' in url or 'nia.nih.gov' in url: return 'PRIMARY_FEDERAL_NIH'
    if 'ncbi.nlm.nih.gov' in url or 'medlineplus.gov' in url: return 'AUTHORITATIVE_NLM_NCBI'
    if 'ahrq.gov' in url: return 'PRIMARY_FEDERAL_AHRQ'
    if 'fda.gov' in url: return 'PRIMARY_FEDERAL_FDA'
    if 'arupconsult.com' in url: return 'AUTHORITATIVE_LAB_ARUP'
    if 'aabb.org' in url: return 'PROFESSIONAL_STANDARD_AABB'
    if 'aasld.org' in url: return 'PROFESSIONAL_GUIDELINE_AASLD'
    if 'pubmed.ncbi.nlm.nih.gov' in url: return 'PEER_REVIEWED_PROFESSIONAL_GUIDELINE'
    if 'nursingworld.org' in url: return 'PROFESSIONAL_STANDARD_ANA'
    if 'asam.org' in url: return 'PROFESSIONAL_GUIDELINE_ASAM'
    if 'mentalhealthfirstaid.org' in url: return 'PRIMARY_PROGRAM_SOURCE_MHFA_USA'
    return 'AUTHORITATIVE_PRIMARY_OR_PROFESSIONAL_SOURCE'
def metrics(opts,key):
    ls={k:len(str(opts[k]).strip()) for k in 'ABCD'}; dm=sum(ls[k] for k in 'ABCD' if k!=key)/3
    return {'characters':ls,'max_min_ratio':round(max(ls.values())/max(min(ls.values()),1),4),'correct_option':key,'correct_deviation_from_distractor_mean':round(abs(ls[key]-dm)/max(dm,1),4),'use':'MEASUREMENT_ONLY_NOT_SEMANTIC_GATE'}
def place_options(authored,target):
    letters='ABCD'; out={}; out[target]=authored[0]; j=1
    for k in letters:
        if k==target: continue
        out[k]=authored[j]; j+=1
    return {k:out[k] for k in letters}
def main():
    if not DB.exists(): raise SystemExit('Current master DB missing')
    pdoc=json.loads(PENDING.read_text(encoding='utf-8'))
    if pdoc.get('range')!=[451,500] or pdoc.get('count')!=50: raise SystemExit(f'Expected pending Batch 010 Q0451-Q0500, got {pdoc.get("range")} count={pdoc.get("count")}')
    rows=pdoc.get('questions',[])
    if [q.get('question_uid') for q in rows]!=IDS: raise SystemExit('Pending questions are not exactly V2-Q0451..V2-Q0500 in order')
    current={q['question_uid']:q for q in rows}; items=[]
    default_cat={v:k for k,v in NEEDS.items()}
    for n in range(451,501):
        uid=f'V2-Q{n:04d}'; q=current[uid]
        cat=CATEGORY_PATCH.get(n,default_cat.get(q['client_need']))
        if cat not in NEEDS: raise SystemExit(f'{uid}: unmapped client need {q["client_need"]}')
        opts=place_options(AUTHORED_OPTIONS[n],TARGET_KEYS[n]); key=TARGET_KEYS[n]
        stem=STEM_PATCH.get(n,q['stem'])
        rationale=RATIONALE_PATCH.get(n,re.sub(r'\bOption\s+[A-D]\b','The keyed response',q['rationale']))
        if n in SOURCE_PATCH:
            sname,surl,locator,version=SOURCE_PATCH[n]
        else:
            sname,surl,locator=q['source_name'],q['source_url'],q['source_detail']
            version='Source has no separate formal version identifier in the cited page metadata; live currentness and applicability rechecked 2026-08-15.'
        finding='Fresh Rule 1 review of stem, four final authored choices, key, rationale, source hierarchy/currentness, blueprint, difficulty, ambiguity, cueing and second-answer risk; final state independently re-read.'
        if n==453: finding+=' Replaced broad mechanism wording with the directly label-supported losartan-versus-lisinopril cough comparison.'
        if n==477: finding+=' Corrected blueprint from Management of Care to Psychosocial Integrity.'
        if n==482: finding+=' Narrowed the stem to portosystemic collateral-vein formation to eliminate overlap with other cirrhosis decompensation complications.'
        if n==490: finding+=' Removed the prior Rh-selection generalization and limited the item to AABB-supported ABO emergency red-cell compatibility.'
        if n==494: finding+=' Corrected blueprint from Basic Care and Comfort to Pharmacological and Parenteral Therapies.'
        if n==495: finding+=' Corrected blueprint from Basic Care and Comfort to Safety and Infection Prevention and Control.'
        if n==500: finding+=' Corrected blueprint from Psychosocial Integrity to Physiological Adaptation.'
        items.append({'id':uid,'cat':cat,'need':NEEDS[cat],'diff':q['difficulty'],'stem':stem,'options':opts,'key':key,'rationale':rationale,'source_name':sname,'source_url':surl,'locator':locator,'version':version,'authority':authority(surl),'finding':finding,'qa':[11,'PASS','FINAL_QA_PASS']})
    # Materialize the five manual audit records. Static data above contains the semantic/editorial decisions; this loop only serializes them.
    for idx,start in enumerate((451,461,471,481,491)):
        chunk=items[idx*10:(idx+1)*10]
        doc={'batch':'Q0451-Q0500','range':f'Q{start:04d}-Q{start+9:04d}','review_date':REVIEW_DATE,'legacy_status_evidence':False,'semantic_decisions_by_script':False,'manual_decision_source':'STATIC_AUTHORED_RULE1_ITEM_BY_ITEM_REVIEW','items':chunk}
        PATCHES[idx].write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    con=sqlite3.connect(DB); con.row_factory=sqlite3.Row; evidence=[]; overrides=[]
    for p in items:
        uid=p['id']; q=con.execute('SELECT * FROM questions WHERE question_uid=?',(uid,)).fetchone()
        if q is None: raise SystemExit(f'{uid}: missing DB row')
        opts=p['options']; key=p['key']
        if set(opts)!=set('ABCD') or key not in opts or len({v.strip().casefold() for v in opts.values()})!=4: raise SystemExit(f'{uid}: invalid options/key')
        if p.get('qa')!=[11,'PASS','FINAL_QA_PASS']: raise SystemExit(f'{uid}: incomplete semantic QA')
        for fld in ('stem','rationale','source_name','source_url','locator','version','authority','need','diff'):
            if not str(p.get(fld,'')).strip(): raise SystemExit(f'{uid}: missing {fld}')
        ncsbn={'required_currentness_and_blueprint_check':True,'source':'NCSBN — 2026 NCLEX-RN Test Plan','url':NCSBN_URL,'locator':NCSBN_LOCATORS[p['cat']],'version':NCSBN_VERSION,'result':'PASS','scope':'Mandatory current NCLEX blueprint/category/entry-level relevance check; exact clinical/legal claim separately verified against the item authority.'}
        m=metrics(opts,key); detail=f"{p['locator']} {p['version']} NCSBN first-check: {ncsbn['locator']} {NCSBN_VERSION}"
        flags=['RULE1_BATCH010_MANUAL_ITEM_BY_ITEM_REAUDIT','LEGACY_STATUS_NOT_USED_AS_EVIDENCE','SEMANTIC_DECISIONS_NOT_BY_SCRIPT','STATIC_MANUAL_AUTHORED_FINAL_OPTIONS','SOURCE_LOCATOR_VERSION_CURRENTNESS_VERIFIED','MANUAL_DISTRACTOR_AMBIGUITY_CUE_SECOND_ANSWER_QC_PASS','INDEPENDENT_SECOND_PASS_QA_PASS','OPTION_LENGTH_METRICS_MEASUREMENT_ONLY']
        overrides.append({'question_uid':uid,'source_id':int(q['source_id']),'category_id':p['cat'],'client_need':p['need'],'difficulty':p['diff'],'stem':p['stem'],'item_data_json':json.dumps({'options':opts},ensure_ascii=False,separators=(',',':')),'correct_answer_json':json.dumps({'correct_option':key},separators=(',',':')),'rationale':p['rationale'],'source_name':p['source_name'],'source_detail':detail,'source_url':p['source_url'],'clinical_qa_status':STATUS,'editorial_priority':'PRODUCTION_CANDIDATE','editorial_flags_json':json.dumps(flags,separators=(',',':')),'qc':{'question_uid':uid,'lengths_json':json.dumps(m['characters'],separators=(',',':')),'min_chars':min(m['characters'].values()),'max_chars':max(m['characters'].values()),'max_min_ratio':m['max_min_ratio'],'correct_option':key,'correct_length_rank':sorted(m['characters'].values()).index(m['characters'][key])+1,'correct_is_extreme':int(m['characters'][key] in (min(m['characters'].values()),max(m['characters'].values()))),'qc_status':'MEASURED_NOT_GATE','qc_note':'Length metrics are measurement only; semantic option/cue/ambiguity decisions are manual.'}})
        evidence.append({'id':uid,'key':key,'category_id':p['cat'],'client_need':p['need'],'difficulty':p['diff'],'source_authority':p['authority'],'source_name':p['source_name'],'source_url':p['source_url'],'source_locator':p['locator'],'source_version':p['version'],'reviewed_at':REVIEW_DATE,'finding':p['finding'],'ncsbn_first_check':ncsbn,'criteria':11,'criteria_names':CRITERIA,'second_pass':'PASS','second_pass_method':'Independent fresh second read of final corrected stem, all four authored options, key, rationale, source locator/version/currentness, blueprint/difficulty and second-answer/cue risk without using legacy status as evidence.','final':'FINAL_QA_PASS','option_measurement':m,'semantic_decision_origin':'MANUAL_ITEM_BY_ITEM_AUDIT_NOT_SCRIPT'})
    con.close()
    EVIDENCE.write_text(json.dumps({'standard':'RULE_1_FINAL_10_OF_10_MANUAL_ITEM_BY_ITEM_REAUDIT','batch':'Q0451-Q0500','review_date':REVIEW_DATE,'legacy_status_evidence':False,'semantic_decisions_by_script':False,'criteria_names':CRITERIA,'ncsbn_test_plan':{'url':NCSBN_URL,'version':NCSBN_VERSION},'items':evidence},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    OVERRIDE.write_text(json.dumps({'version':'2026-08-15-rule1-batch010-manual-item-by-item-q0451-q0500','semantic_decisions_by_script':False,'questions':overrides},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('BATCH010_MANUAL_ARTIFACTS_BUILT items=50/50 criteria11=50/50 second_pass=50/50 semantic_script_decisions=0 option_metrics=measurement_only')
if __name__=='__main__': main()
